// What the dashboard (Site content tab) changed on the public site: links, numbers, words, pictures, lists and past events.
// You do not edit this file.
//
// How it works: everything written in src/data/site.js (and the words listed below) stays the DEFAULT. Once per visit the site asks
// /api/settings what the admin changed (site/liveSettings.js). Whatever the admin changed wins, everything else stays as in the files.
// A picture the admin uploads and a picture put in src/assets with git go through the same frames on the page, so they fit the same way.
import { useMemo } from 'react';
import * as D from '../data/site';
import { liveValue, useLiveSettings } from './liveSettings';
import { mediaUrl } from './eventLive';

// builds a value once per saved object (the object stays the same until the next answer from /api/settings)
const cache = new WeakMap();
const once = (raw, make) => {
  if (!raw || typeof raw !== 'object') return null;
  let v = cache.get(raw);
  if (v === undefined) { v = make(raw); cache.set(raw, v); }
  return v;
};

/* ---------- links ---------- */
export function currentLinks() {
  const o = liveValue('siteLinks', null);
  return o && typeof o === 'object' ? once(o, (x) => ({ ...D.LINKS, ...x })) : D.LINKS;
}
export function useLinks() { useLiveSettings(); return currentLinks(); }
// a button inside a list that still has the link from the code file follows the link set in the dashboard
const relink = (href) => {
  const l = currentLinks();
  for (const k of Object.keys(D.LINKS)) if (href === D.LINKS[k]) return l[k];
  return href;
};

/* ---------- the four numbers ---------- */
export function useStats() {
  useLiveSettings();
  const v = liveValue('siteStats', null);
  return Array.isArray(v) && v.length ? v : D.STATS;
}

/* ---------- headings and sentences ---------- */
export const SITE_TEXT_DEFAULTS = {
  heroPill: 'Sipna College of Engineering & Technology',
  heroLine1: 'Compile your',
  heroGrad: 'future',
  heroSub: 'Not just a club. A runtime environment for the next generation of software engineers. Build, break, and ship code that matters.',
  joinTitle: 'Join Coders Community',
  joinSub: "Registrations are open. Three simple steps and you're in.",
  pastTitle: "What we've done",
  pastSub: 'Workshops, hackathons and seminars. Tap any event to see the photos.',
  doTitle: 'Learn by building',
  doSub: 'Pick a track, learn with friends and ship something real.',
  faqTitle: 'Questions, answered',
  faqSub: 'Everything people usually ask us before joining.',
  crewTitle: 'The founding crew',
  crewText: 'The members who started Sipna Coders Club and built the community we have today.',
};
export function useText() {
  useLiveSettings();
  const o = liveValue('siteText', null);
  return o && typeof o === 'object' ? once(o, (x) => ({ ...SITE_TEXT_DEFAULTS, ...x })) : SITE_TEXT_DEFAULTS;
}

/* ---------- the two big pictures ---------- */
export const FILE_POSTER_RATIO = 1414 / 2000;   // the membership poster in src/assets/posters (a different shape is measured when it loads)
// o = what the dashboard saved for the pictures ({ membership: { v, r }, group: { v, pos } }) or nothing
export function picturesFrom(o) {
  const m = o && o.membership, g = o && o.group;
  return {
    membership: m && m.v ? { src: mediaUrl('s-membership', m.v), ratio: m.r || FILE_POSTER_RATIO, admin: true } : { src: D.membershipPoster, ratio: FILE_POSTER_RATIO, admin: false },
    group: g && g.v ? { src: mediaUrl('s-group', g.v), pos: typeof g.pos === 'number' ? g.pos : 50, admin: true } : { src: D.groupPhoto, pos: 50, admin: false },
  };
}
export function usePictures() {
  useLiveSettings();
  return picturesFrom(liveValue('sitePictures', null));
}

/* ---------- simple lists ---------- */
const listOr = (key, file) => {
  const v = liveValue(key, null);
  return Array.isArray(v) ? v : file;
};
export function useFaq() {
  useLiveSettings();
  const raw = listOr('faq', D.FAQ);
  const links = currentLinks();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useMemo(() => raw.map((f) => (f.link && f.link.href ? { ...f, link: { ...f.link, href: relink(f.link.href) } } : f)), [raw, links]);
}
export function useJoinSteps() { useLiveSettings(); return listOr('joinSteps', D.JOIN_STEPS); }
export function useTracks() { useLiveSettings(); return listOr('tracks', D.TRACKS); }
export function useTools() { useLiveSettings(); return listOr('tools', D.TOOLS); }
export function useWins() { useLiveSettings(); return listOr('wins', D.WINS); }
export function useVoices() { useLiveSettings(); return listOr('voices', D.VOICES); }

/* ---------- past events ---------- */
// a saved event -> the shape used by the pages: images become plain picture addresses
export function buildPast(list) {
  return list.map((e) => {
    const code = e.key ? D.pastEvents.find((c) => c.id === e.key) : null;
    const images = (e.images || []).map((im) => (im.c !== undefined ? (code && code.images ? code.images[im.c] : null) : mediaUrl(im.id, im.v))).filter(Boolean);
    return { id: e.key || e.id, title: e.title, category: e.category, date: e.date, sortDate: e.sortDate, description: e.description, images };
  });
}
export function currentPastEvents() {
  const v = liveValue('pastEvents', null);
  return Array.isArray(v) ? once(v, buildPast) : D.pastEvents;
}
export function usePastEvents() { useLiveSettings(); return currentPastEvents(); }
